EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Placeholder for the current position in the data stream
    uint64 position = DataStream.getPosition();
    uint64 remainingSize = MaxDataSize;

    // Read the next potential ID from the data stream
    EbmlId id;
    if (!DataStream.read(id))
        return nullptr;

    if (DataStream.getError())
        return nullptr;

    // Calculate the size of the element
    EbmlUInteger size;
    if (!size.read(DataStream))
        return nullptr;

    if (DataStream.getError())
        return nullptr;

    uint64 elementSize = size.getValue();
    remainingSize -= size.getByteCount();

    // Validate the size and remaining data
    if (elementSize > remainingSize)
        return nullptr;

    // Check for dummy element constraints
    if (AllowDummyElt && id == 0)
        return new EbmlDummyElement();

    // Create and initialize the EBML element
    EbmlElement* element = Context.createElement(id);
    if (!element)
        return nullptr;

    element->setElementSize(elementSize);
    element->setPosition(position);
    element->setContext(Context);

    // Check lower level constraint
    if (element->getLevel() > MaxLowerLevel)
        return nullptr;

    // Update the upper level
    UpperLevel = element->getLevel();

    return element;
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 bytesRead = 0;
    uint8 id = 0;
    uint64 size = 0;
    int result;

    // Read the next potential ID
    result = DataStream.read(&id, sizeof(id));
    if (result != sizeof(id)) {
        return nullptr;
    }
    bytesRead += sizeof(id);

    // Determine the size of the element
    size = readEbmlSize(DataStream, MaxDataSize - bytesRead);
    if (size == 0) {
        return nullptr;
    }
    bytesRead += getEbmlSizeSize(size);

    // Check if the total size exceeds the maximum allowed data size
    if (bytesRead + size > MaxDataSize) {
        return nullptr;
    }

    // Create a temporary element to check constraints
    EbmlElement* tempElement = new EbmlElement();
    if (!tempElement->setID(id, Context)) {
        delete tempElement;
        return nullptr;
    }

    // Check hierarchy level constraints
    int elementLevel = tempElement->getLevel();
    if (elementLevel > MaxLowerLevel || (UpperLevel != -1 && elementLevel <= UpperLevel)) {
        delete tempElement;
        return nullptr;
    }

    // Check for dummy elements
    if (tempElement->isDummy() && !AllowDummyElt) {
        delete tempElement;
        return nullptr;
    }

    // Update the upper level
    UpperLevel = elementLevel;

    // Create the full element if constraints are met
    EbmlElement* element = new EbmlElement();
    if (!element->setID(id, Context)) {
        delete element;
        return nullptr;
    }

    if (!element->setSize(size)) {
        delete element;
        return nullptr;
    }

    return element;
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 pos = DataStream.tellg();
    if (pos >= MaxDataSize) {
        return nullptr;
    }

    uint64 id = 0;
    uint64 size = 0;
    if (!DataStream.readId(id)) {
        return nullptr;
    }

    if (!DataStream.readSize(size)) {
        return nullptr;
    }

    if (pos + size > MaxDataSize) {
        return nullptr;
    }

    EbmlElement* element = Context.createElement(id);
    if (!element) {
        if (!AllowDummyElt) {
            return nullptr;
        }
        element = new EbmlDummyElement(id, size);
    }

    if (!element->validateLevel(UpperLevel, MaxLowerLevel)) {
        delete element;
        return nullptr;
    }

    return element;
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Attempt to read potential EBML element ID and size
    uint64 currentPos = DataStream.GetPos();
    if (currentPos >= MaxDataSize) {
        return NULL;
    }

    // Read the element ID from the stream
    EbmlId elementId;
    if (!DataStream.Read(elementId)) {
        return NULL;
    }

    // Read the size of the element
    EbmlSize elementSize;
    if (!DataStream.Read(elementSize)) {
        return NULL;
    }

    // Calculate the end position of the element based on its size
    uint64 elementEnd = DataStream.GetPos() + elementSize;
    if (elementEnd > MaxDataSize) {
        return NULL; // Element exceeds the maximum data size
    }

    // Check if the current level exceeds the maximum allowed lower level
    if (UpperLevel > static_cast<int>(MaxLowerLevel)) {
        return NULL;
    }

    // Create an EBML element based on the context and ID
    EbmlElement *element = Context.Create(elementId);
    if (!element) {
        if (!AllowDummyElt) {
            return NULL;
        }
        // Create a dummy element if allowed
        element = new EbmlElement();
        if (!element) {
            return NULL; // Out of memory
        }
    }

    // Set the size of the element
    element->SetSize(elementSize);

    // Update the current upper level
    ++UpperLevel;

    return element;
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Implementation based on the logic provided in the docstring.

    // Attempt to read the element ID from the stream.
    uint8 idBuffer[8];
    int bytesRead = DataStream.Read(idBuffer, 1);
    if (bytesRead <= 0) {
        return nullptr;
    }

    uint8 idSize = idBuffer[0] & 0x80 ? idBuffer[0] & 0x0F : 1;
    if (idSize > 8) {
        return nullptr;
    }

    for (int i = 1; i < idSize; ++i) {
        bytesRead = DataStream.Read(&idBuffer[i], 1);
        if (bytesRead <= 0) {
            return nullptr;
        }
    }

    uint64 elementSize = 0;
    for (int i = 0; i < idSize; ++i) {
        elementSize = (elementSize << 8) | idBuffer[i];
    }

    if (elementSize == 0 && !AllowDummyElt) {
        return nullptr;
    }

    // Check if reading the element would exceed the MaxDataSize.
    if (MaxDataSize < idSize + (elementSize > 0 ? elementSize : 0)) {
        return nullptr;
    }

    // Create the EBML element using the context.
    EbmlElement* element = Context.CreateEbmlElement(idBuffer, idSize);
    if (!element) {
        return nullptr;
    }

    // Check if the element's level exceeds the maximum allowed level.
    if (element->GetLevel() > MaxLowerLevel) {
        delete element;
        return nullptr;
    }

    // Read the element's data if it's not a dummy element.
    if (elementSize > 0) {
        uint8* data = new uint8[elementSize];
        bytesRead = DataStream.Read(data, elementSize);
        if (bytesRead != static_cast<int>(elementSize)) {
            delete[] data;
            delete element;
            return nullptr;
        }

        element->SetData(data, elementSize);
    }

    UpperLevel = element->GetLevel();
    return element;
}
